from lib import *
S = SS('k40')
F1 = [['打污点前:8 个 Pod', 'worker=2'], ['打 k40=a:NoSchedule', ''], ['之后新建 8 个', 'worker 上 0 个'], ['原来的 2 个', '没被动']]
F2 = [['无污点 12 个副本', '3/3/3/3'], ['PreferNoSchedule', '4/4/4(worker 0)'], ['Pod 只能去 worker', '照样调度 3 个']]
F3 = [['打 NoExecute 污点', 'T0'], ['no-tol', '0.1 秒被驱逐'], ['tol-8s', '8.4 秒被驱逐'], ['tol-forever', '一直留着']]
F4 = [['不写容忍', '准入补 not-ready / unreachable 各 300 秒'], ['指向控制面,无容忍', 'Pending: untolerated taint'], ['指向控制面,有容忍', 'Running 在 control-plane']]
PANELS = [('f', 'flow', '污点与容忍'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("先创建 8 个副本(此时 worker=2 worker2=2 worker3=2 worker4=2),再给 worker 打 k40=a:NoSchedule:之后创建的 8 个副本 worker 上一个都没有(2/3/3),之前 worker 上的 2 个 Pod 没被动。固定要放到 worker 上的 Pod:容忍 {key: k40, operator: Equal, value: a, effect: NoSchedule} → 4 个 Running;value 写成 b → 全部 Pending(2 node(s) had untolerated taint(s), 3 node(s) didn't match Pod's node affinity/selector);{key: k40, operator: Exists} → 4 个 Running;{operator: Exists}(空 key)→ 4 个 Running。", f=fl(F1, cur=[2], done=[0, 3], mark=[1]), t=tl(S(1), mark=lidx(S(1), 'worker 上一个都没有', 'value: b'), done=lidx(S(1), 'value: a', 'operator: Exists')), kv=KV([['NoSchedule', '只挡新调度,不赶走已有的'], ['Equal', 'key、value、effect 都要匹配'], ['Exists', '只看 key;空 key 的 Exists 容忍一切污点']], ['NoSchedule'])),
    step("PreferNoSchedule:没有污点时 12 个副本 3/3/3/3;给 worker 打上之后 12 个副本落在 worker2、worker3、worker4 各 4 个,worker 上 0 个;但如果 Pod 只能去 worker(nodeSelector),3 个照样调度成功——软污点不阻止调度。", f=fl(F2, cur=[1, 2]), t=tl(S(2), mark=lidx(S(2), 'worker 打上 PreferNoSchedule', '软的污点不阻止'), done=lidx(S(2), '没有污点')), kv=KV([['PreferNoSchedule', '调度器尽量避开,没得选时仍会用'], ['适用场景', '“最好别放这”而不是“绝对不行”']], ['PreferNoSchedule'])),
    step("NoExecute 连正在运行的 Pod 也要赶走:worker 上有 3 个裸 Pod,打上 k40=a:NoExecute 后——没有容忍的 no-tol 在 0.1 秒被驱逐;tolerationSeconds=8 的 tol-8s 在 8.4 秒被驱逐;容忍但没写秒数的 tol-forever 25 秒后仍在运行。", f=fl(F3, cur=[1, 2], done=[3]), t=tl(S(3), mark=lidx(S(3), 'no-tol  ', 'tol-8s'), done=lidx(S(3), 'tol-forever')), kv=KV([['NoExecute', '会驱逐已经在运行的 Pod'], ['tolerationSeconds', '容忍多久之后才被驱逐'], ['不写秒数', '永远容忍']], ['NoExecute'])),
    step("没写也存在的容忍:一个什么容忍都没写的 Pod,spec.tolerations 被准入补上了 node.kubernetes.io/not-ready:NoExecute 与 node.kubernetes.io/unreachable:NoExecute,各 tolerationSeconds=300。控制面节点自带 node-role.kubernetes.io/control-plane:NoSchedule:nodeSelector 指向控制面、没有容忍的 Pod Pending(1 node(s) had untolerated taint(s), 4 node(s) didn't match Pod's node affinity/selector);加上这个容忍后 Running 在 kx-sched-control-plane。", f=fl(F4, cur=[0, 1], done=[2]), t=tl(S(4), mark=lidx(S(4), '没有对 control-plane 污点的容忍'), done=lidx(S(4), '被准入补上', '写了对 control-plane 污点的容忍')), kv=KV([['默认的 300 秒', '节点失联后 Pod 最多再留 5 分钟'], ['控制面污点', '让业务 Pod 默认不上控制面'], ['想用控制面', '要显式写容忍']], ['默认的 300 秒'])),
]
A = mkartk('k40', 40, 'Kubernetes,污点,容忍,taint,toleration,NoSchedule,NoExecute,真实验证,动画演示',
    '在 5 节点 kind 集群里实测污点与容忍:NoSchedule 只挡新调度、不动已有 Pod,Equal 要 value 也匹配而 Exists 只看 key、空 key 的 Exists 容忍一切;PreferNoSchedule 让 12 个副本避开该节点但 Pod 只能去它时仍会调度;NoExecute 会驱逐运行中的 Pod:无容忍 0.1 秒、tolerationSeconds=8 时 8.4 秒、不写秒数则一直留着;准入会自动补 not-ready/unreachable 各 300 秒的容忍,控制面的 NoSchedule 污点需要显式容忍才能调度上去。',
    '污点和容忍到底怎么匹配?NoSchedule、PreferNoSchedule、NoExecute 三种效果差在哪?已经在运行的 Pod 会被赶走吗?这篇用一个 5 节点集群,把三种效果、四种容忍写法和“没写也存在的容忍”都逐个跑出来。',
    [('0.1 / 8.4 / 不驱逐', 'NoExecute 污点打上后,无容忍、tolerationSeconds=8、不写秒数的 Pod 被驱逐的时间'), ('2 / 3 / 3', 'worker 被打上 NoSchedule 之后新建的 8 个副本在 worker2 / worker3 / worker4 上的分布(worker 上 0 个)'), ('300 秒', '准入自动给每个 Pod 补上的 not-ready / unreachable 容忍的 tolerationSeconds')],
    [('NoSchedule 与容忍写法', '<p>先放 8 个副本(每个 worker 2 个),再给 <code>worker</code> 打 <code>k40=a:NoSchedule</code>。之后新建的 8 个副本 worker 上一个都没有,原来那 2 个也没被动——NoSchedule 只挡新调度。固定去 worker 的 Pod:容忍 <code>Equal</code> 且 <code>value: a</code> 能上;<code>value: b</code> 全部 Pending(<code>2 node(s) had untolerated taint(s), 3 node(s) didn\'t match Pod\'s node affinity/selector</code>);<code>operator: Exists</code> 只看 key 也能上;空 key 的 <code>operator: Exists</code> 容忍所有污点。</p>'),
     ('PreferNoSchedule', '<p>没有污点时 12 个副本 3/3/3/3;worker 打上 <code>PreferNoSchedule</code> 后 12 个副本全落在另外三个节点(4/4/4),worker 上 0 个;但 Pod 如果只能去 worker(<code>nodeSelector</code>),3 个照样调度成功。软污点只影响打分,不阻止调度。</p>'),
     ('NoExecute', '<p>NoExecute 会驱逐已经在运行的 Pod。worker 上 3 个裸 Pod,打上 <code>k40=a:NoExecute</code> 之后:没有容忍的 <code>no-tol</code> 0.1 秒就被驱逐;容忍且 <code>tolerationSeconds: 8</code> 的 8.4 秒被驱逐;容忍但没写 <code>tolerationSeconds</code> 的 25 秒后仍在运行。节点失联时的驱逐(下面第四节的默认容忍)用的是同一套机制。</p>'),
     ('没写也存在的容忍', '<p>创建时没写任何容忍的 Pod,<code>spec.tolerations</code> 里被准入补上了 <code>node.kubernetes.io/not-ready:NoExecute</code> 和 <code>node.kubernetes.io/unreachable:NoExecute</code>,各 <code>tolerationSeconds: 300</code>。控制面节点自带 <code>node-role.kubernetes.io/control-plane:NoSchedule</code>:<code>nodeSelector</code> 指向控制面却没有容忍的 Pod 是 <code>Pending</code>,加上容忍之后 Running 在 <code>kx-sched-control-plane</code>。</p>')],
    steps,
    [ENV_K + '。独立的 5 节点 kind 集群 kx-sched(1 控制面 + 4 个 worker,Kubernetes v1.37.0,与前两篇共用),污点在实验中打上、实验后移除;副本的分布取自每个 Pod 的 spec.nodeName;第 3 节的 3 个 Pod 是用 nodeName 固定在 worker 上的裸 Pod,0.25 秒间隔轮询其是否出现 deletionTimestamp 或消失(第一次运行因为 YAML 缩进写错导致 Pod 没创建、得到了“全被立即驱逐”的假结果,已修正并加了运行断言);第 4 节的控制面用 nodeSelector node-role.kubernetes.io/control-plane 指向;每种情形各一次',
     '没有验证:节点失联(NotReady)时自动打上的 node.kubernetes.io/not-ready 与 unreachable 污点和 300 秒的完整时间线(后面有专门的文章);节点条件污点(memory-pressure 等)的容忍;DaemonSet 自动带的容忍;tolerationSeconds 对已经 Terminating 的 Pod 的影响;污点与亲和的组合;kubectl drain 打的 unschedulable 污点'],
    '污点与容忍', PANELS)
